# --- benchmark ---
import json

records = json.loads(TEXT)['results']
term = '请求超时'
matches = []
for row in records:
    if row['status'] != 'open':
        continue
    body = row['body']
    folded = body.lower()
    position = folded.find(term)
    if position < 0:
        continue
    score = row['priority'] * 10 + folded.count(term)
    excerpt = ' '.join(body[max(0, position - 40):position + 200].split())
    matches.append((score, row['id'], row['title'], row['author'], excerpt, row['url']))

matches.sort(key=lambda row: (-row[0], row[1]))
top = matches[:20]
lines = []
for score, identifier, title, author, excerpt, url in top:
    lines.append(f'- [{identifier}] {title} ({author})\n  {excerpt}\n  {url}')
report = '\n'.join(lines)
assert len(records) == 64
assert len(top) == 20
print(len(records), len(matches), sum(row[1] for row in top), len(report))
